import json

# Search through all elements in both JSON files
for fname in ['/app/resources/treasury_bulletin_1960_01.json', '/app/resources/treasury_bulletin_1960_02.json']:
    data = json.load(open(fname))
    for el in data.get('document', {}).get('elements', []):
        content = el.get('content', '')
        if content and isinstance(content, str):
            # Look for exchange-related content
            if 'exchange' in content.lower() or 'canada' in content.lower():
                print(f'{fname}: {content[:200]}')"
